import java.util.Scanner;

interface ServiceRate {
    int RATE = 20;
}

interface HandlingRate {
    int RATE = 10;
}

class BillingCalculator implements ServiceRate, HandlingRate {
    public int calculate(int factor) {
        // Bug 1: Ambiguous reference to RATE
        // Bug 2: Attempting to modify interface constant
        RATE = RATE + 5; 
        return factor * RATE;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int factor = sc.nextInt();
        BillingCalculator calc = new BillingCalculator();
        System.out.println("Total Charge: " + calc.calculate(factor));
    }
}
